import{_ as t,o as i,c as a,a3 as s}from"./chunks/framework.BwzYn71E.js";const g=JSON.parse('{"title":"关于神秘常数11.8/h的相关探究（已被抛弃）","description":"","frontmatter":{"translationSource":{"title":"关于神秘常数11.8/h的相关探究（已被抛弃）","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Aoh27KC22zbHpXeBVPKXpY","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/investigating-the-mysterious-constant-11-8-h"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/investigating-the-mysterious-constant-11-8-h"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/investigating-the-mysterious-constant-11-8-h"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/investigating-the-mysterious-constant-11-8-h"}]]},"headers":[],"relativePath":"zh/investigating-the-mysterious-constant-11-8-h.md","filePath":"zh/page-Aoh27KC22zbHpXeBVPKXpY.md"}'),o={name:"zh/investigating-the-mysterious-constant-11-8-h.md"};function n(r,e,h,l,d,p){return i(),a("div",null,[...e[0]||(e[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="关于神秘常数11-8-h的相关探究-已被抛弃" aria-hidden="true"></span><h1 id="关于神秘常数11-8-h的相关探究-已被抛弃" tabindex="-1">关于神秘常数11.8/h的相关探究（已被抛弃） <a class="header-anchor" href="#关于神秘常数11-8-h的相关探究-已被抛弃" aria-label="Permalink to &quot;关于神秘常数11\\.8/h的相关探究（已被抛弃）&quot;">​</a></h1><blockquote><p>源页面 ID：<code>Aoh27KC22zbHpXeBVPKXpY</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Aoh27KC22zbHpXeBVPKXpY" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><details><summary>问题简述：</summary><ol><li><p>在反应池吞液现象研究中，满材料反应池反应5小时5*1800=9000次反应有59次吞液，约每小时吞液11.8次，两次测试结果相同，在一小时实验中1800次反应吞液11次，得到满材料反应池吞液速度约为11.8次/h</p></li><li><p>在如下图实验中，每次输出卡顿都会导致溢流箱中物品增加1，经测试，约每5分钟1个物品，折合12/h，时间较长后该速度降低，可能接近11.8/h <img src="/endfield-skydoc/logistics/src/assets/images/img-155e0bd6c2f34e94.q90-5d34a0d6c786d943.webp" alt="关于神秘常数118/h的相关探究（已被抛弃）"></p></li><li><p>在天井院进行同时<s>抽水和放水</s>水泵和给水器同时工作的水循环，损失液滴为11~11.92/h约为11.8/h</p></li></ol><p>以上的巧(必)合(然)引起我们注意，如果后续有相关的降速现象或许可以尝试测速，可能与这个常数相关，值得注意的是，其可能是以11.8次延迟/1800次输出为单位而不是以h^-1为单位</p></details><p>在2026/3/21时反应池吞液被修复，而另外两者没变化，考虑它们之间的联系可能并不紧密，该探究可能并不成立</p><p>在2026/3/30清晨时传送带降速被修复，该命题将在不久后抛弃</p></div>',1)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
